local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local SmokeEffect = CS.SmokeEffect

---@class ScreenFogEffect : BaseEffect
local ScreenFogEffect = Class("ScreenFogEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")

function ScreenFogEffect:__init()
    self.TargetColor = nil
    self._isFinish = nil
end

function ScreenFogEffect:__delete()
    self.TargetColor = nil
    self._isFinish = nil
end

---@param parameters NewChapter2DVo
function ScreenFogEffect:Initialize(parameters)
    base.Initialize(self, parameters)
    if parameters.screenAnim == NewChapterConstants.ScreenEffect.ScreenBlackFog then
        self.TargetColor = Color.New(0,0,0,1)
    elseif parameters.screenAnim == NewChapterConstants.ScreenEffect.ScreenWhiteFog then
        self.TargetColor = Color.New(1,1,1,1)
    end
end

function ScreenFogEffect:StartEffect(object)
    base.StartEffect(self, object)
    local effect = object.gameObject:GetComponent(typeof(SmokeEffect))
    if isNull(effect) then
        return
    end
    effect.enabled = true
    effect.SmokeColor = self.TargetColor
    effect.SmokeAlpha = 1
end

function ScreenFogEffect:IsFinish()
    base.IsFinish(self)
    return false
end

function ScreenFogEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function ScreenFogEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    local effect = object.gameObject:GetComponent(typeof(SmokeEffect))
    if isNull(effect) then
        return
    end
    effect.enabled = false
    --effect.SmokeColor = self.TargetColor
    effect.SmokeAlpha = 0
end

return ScreenFogEffect